import inspect
from functools import wraps, partial
import asyncio

async def iscoroutinefunction(f):
    return inspect.iscoroutinefunction(f)

def check_coroutine(call):
    curr = call
    while True:
        if curr is None:
            return False
        if inspect.iscoroutinefunction(curr):
            return True
        if isinstance(curr, partial):
            curr = curr.func
            continue
        dunder_call = getattr(curr, "__call__", None)
        if dunder_call and inspect.iscoroutinefunction(dunder_call):
            return True
        unwrapped = inspect.unwrap(curr)
        if unwrapped is curr:
            break
        curr = unwrapped
    return False

async def async_func():
    return 1

def sync_func():
    return 1

@wraps(sync_func)
async def async_wrapper(*args, **kwargs):
    return sync_func(*args, **kwargs)

@wraps(async_func)
def sync_wrapper(*args, **kwargs):
    return async_func(*args, **kwargs)

class AsyncCallable:
    async def __call__(self):
        return 1

class SyncCallable:
    def __call__(self):
        return 1

print(f"async_func: {check_coroutine(async_func)}") # True
print(f"sync_func: {check_coroutine(sync_func)}") # False
print(f"async_wrapper: {check_coroutine(async_wrapper)}") # True
print(f"sync_wrapper: {check_coroutine(sync_wrapper)}") # True (because it wraps async_func)
print(f"AsyncCallable: {check_coroutine(AsyncCallable())}") # True
print(f"SyncCallable: {check_coroutine(SyncCallable())}") # False

p_async = partial(async_func)
print(f"partial(async_func): {check_coroutine(p_async)}") # True

p_sync = partial(sync_func)
print(f"partial(sync_func): {check_coroutine(p_sync)}") # False

p_async_wrapper = partial(async_wrapper)
print(f"partial(async_wrapper): {check_coroutine(p_async_wrapper)}") # True

p_sync_wrapper = partial(sync_wrapper)
print(f"partial(sync_wrapper): {check_coroutine(p_sync_wrapper)}") # True

# Combined wraps and partial
@wraps(sync_func)
async def async_wrapper_2(*args, **kwargs):
    return sync_func(*args, **kwargs)

p_async_wrapper_2 = partial(async_wrapper_2)
print(f"partial(async_wrapper_2): {check_coroutine(p_async_wrapper_2)}") # True

# Wrapped partial
def wrap_partial(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

p_async = partial(async_func)
wrapped_p_async = wrap_partial(p_async)
print(f"wrap_partial(partial(async_func)): {check_coroutine(wrapped_p_async)}") # True

# Partial of wrapped async
async def async_f():
    return 1
def wrap_async(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper
wrapped_async = wrap_async(async_f)
p_wrapped_async = partial(wrapped_async)
print(f"partial(wrap_async(async_f)): {check_coroutine(p_wrapped_async)}") # True
